SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(4*10^9);tt:=Cputime();AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");out:=[* *];
for n in [27,81] do J:=n eq 27 select JOne(27) else JZero(81);fp:=FrobeniusPolynomial(J,2);if Type(fp) eq SeqEnum then fp:=&*fp;end if;Append(~out,[*n,Dimension(J),Coefficients(fp),Integers()!Evaluate(fp,1)*]);print "C81_SMALL_TARGET_FROBENIUS",n,Dimension(J),Evaluate(fp,1),Cputime(tt);end for;
for u in [28,10,4] do J:=JH(81,[u]);print "C81_DIAMOND_QUOTIENT_GENUS",u,Dimension(J),Cputime(tt);if Dimension(J) le 13 then fp:=FrobeniusPolynomial(J,2);if Type(fp) eq SeqEnum then fp:=&*fp;end if;Append(~out,[*u,Dimension(J),Coefficients(fp),Integers()!Evaluate(fp,1)*]);end if;end for;
CQ:=SmallModularCurve(81);CC:=ChangeRing(CQ,GF(2));print "C81_X0_MODEL",Genus(CC),IsNonsingular(CC),Ambient(CC),Cputime(tt);Write("work/deg10/continuation_20261030b/C81/target_assessment.m",Sprint(out):Overwrite:=true);print "C81_TARGET_ASSESSMENT_COMPLETE",Cputime(tt);quit;
